import{_ as e,C as l,o as t,c as r,j as i,E as d,a as n,a2 as s}from"./chunks/framework.C21TwvGF.js";const p=JSON.parse('{"title":"1-hafta","description":"","frontmatter":{"title":"1-hafta","layout":"doc","sidebar":false,"aside":false,"outline":false,"kind":"hafta","hafta":{"sinf":{"name":"10-sinf (Android)","link":"/10-sinf-android/"},"n":1,"bob":"I-bob · Android loyihalarini boshqarish va versiya nazorati tizimlari","lessons":[{"g":1,"title":"1-dars: Gradle konfiguratsiyasi va build tizimi asoslari","lead":"Gradle konfiguratsiyasi va build tizimi asoslari: settings.gradle, build.gradle, SDK versiyalari","link":"/10-sinf-android/hafta-01/dars-1","slide":"/slaydlar/10-sinf-android/hafta-01/dars-1.html","test":"/slaydlar/10-sinf-android/hafta-01/dars-1-test.html"},{"g":2,"title":"2-dars: Build variantlari va Product Flavors","lead":"Build variantlari va Product Flavors: Debug vs Release, R8 optimallashtirish, BuildConfig","link":"/10-sinf-android/hafta-01/dars-2","slide":"/slaydlar/10-sinf-android/hafta-01/dars-2.html","test":"/slaydlar/10-sinf-android/hafta-01/dars-2-test.html"},{"g":3,"title":"3-dars: Dependency management va versiyalar bilan ishlash (Version Catalog)","lead":"Dependency management va versiyalar bilan ishlash: kutubxonalar, repozitoriylar, Version Catalog (TOML)","link":"/10-sinf-android/hafta-01/dars-3","slide":"/slaydlar/10-sinf-android/hafta-01/dars-3.html","test":"/slaydlar/10-sinf-android/hafta-01/dars-3-test.html"}],"test":"/slaydlar/10-sinf-android/hafta-01/hafta-test.html"}},"headers":[],"relativePath":"10-sinf-android/hafta-01/index.md","filePath":"10-sinf-android/hafta-01/index.md"}'),u={name:"10-sinf-android/hafta-01/index.md"},c={class:"blk"},g={id:"uyga-vazifa",tabindex:"-1"};function f(h,a,v,b,q,m){const o=l("Icon");return t(),r("div",null,[i("div",c,[i("h2",g,[d(o,{name:"house"}),a[0]||(a[0]=n(" Uyga vazifa ",-1)),a[1]||(a[1]=i("a",{class:"header-anchor",href:"#uyga-vazifa","aria-label":'Permalink to "<Icon name="house" /> Uyga vazifa"'},"​",-1))]),a[2]||(a[2]=s('<p>Mazkur haftada o&#39;tilgan darslar bo&#39;yicha mustaqil bajarish uchun topshiriqlar. Har bir vazifa 20–30 daqiqaga mo&#39;ljallangan.</p><hr><h3 id="_1-dars-gradle-konfiguratsiyasi-va-build-tizimi-asoslari" tabindex="-1">1-dars: Gradle konfiguratsiyasi va build tizimi asoslari <a class="header-anchor" href="#_1-dars-gradle-konfiguratsiyasi-va-build-tizimi-asoslari" aria-label="Permalink to &quot;1-dars: Gradle konfiguratsiyasi va build tizimi asoslari&quot;">​</a></h3><ol><li>Android Studio&#39;da yangi bo&#39;sh loyiha yarating va <code>app/build.gradle</code> (yoki <code>.kts</code>) faylidagi quyidagi parametrlarni o&#39;zgartiring: <ul><li><code>minSdk</code> qiymatini 24 qilib belgilang;</li><li><code>targetSdk</code> va <code>compileSdk</code> qiymatlarini 34 qilib o&#39;rnating;</li><li><code>versionCode</code>ni 1, <code>versionName</code>ni esa <code>&quot;1.0.0-alpha&quot;</code> deb belgilang.</li></ul></li><li>&quot;Sync Now&quot; tugmasini bosing va loyihani sinxronizatsiya qiling.</li><li>Terminal ochib, <code>./gradlew tasks</code> buyrug&#39;ini ishga tushiring va ekranda chiqqan asosiy task guruhlaridan (masalan, <code>Build tasks</code>, <code>Verification tasks</code>) 3 tasini daftaringizga yozib qo&#39;ying.</li></ol><hr><h3 id="_2-dars-build-variantlari-va-product-flavors" tabindex="-1">2-dars: Build variantlari va Product Flavors <a class="header-anchor" href="#_2-dars-build-variantlari-va-product-flavors" aria-label="Permalink to &quot;2-dars: Build variantlari va Product Flavors&quot;">​</a></h3><ol><li>O&#39;zingiz yaratgan loyihaning <code>build.gradle</code> fayliga <code>productFlavors</code> blokini qo&#39;shing: <ul><li><code>flavorDimensions &quot;edition&quot;</code> deb o&#39;lchov guruhini e&#39;lon qiling;</li><li><code>free</code> flavorni yarating: <code>applicationIdSuffix &quot;.free&quot;</code> va <code>buildConfigField &quot;boolean&quot;, &quot;IS_PAID&quot;, &quot;false&quot;</code>;</li><li><code>pro</code> flavorni yarating: <code>applicationIdSuffix &quot;.pro&quot;</code> va <code>buildConfigField &quot;boolean&quot;, &quot;IS_PAID&quot;, &quot;true&quot;</code>.</li></ul></li><li>Loyihani sinxronizatsiya qilib, Android Studio&#39;ning &quot;Build Variants&quot; panelidan navbatma-navbat <code>freeDebug</code> va <code>proDebug</code> variantlarini tanlang.</li><li><code>MainActivity.kt</code> faylida <code>BuildConfig.IS_PAID</code> qiymatini tekshiruvchi sodda shart yozing va emulyatorda ishga tushiring.</li></ol><hr><h3 id="_3-dars-dependency-management-va-versiyalar-bilan-ishlash-version-catalog" tabindex="-1">3-dars: Dependency management va versiyalar bilan ishlash (Version Catalog) <a class="header-anchor" href="#_3-dars-dependency-management-va-versiyalar-bilan-ishlash-version-catalog" aria-label="Permalink to &quot;3-dars: Dependency management va versiyalar bilan ishlash (Version Catalog)&quot;">​</a></h3><ol><li>Loyihangizning <code>gradle/libs.versions.toml</code> fayliga kiring va quyidagi yangi kutubxona parametrlarini kiriting: <ul><li><code>[versions]</code> bo&#39;limida: <code>retrofit = &quot;2.9.0&quot;</code>;</li><li><code>[libraries]</code> bo&#39;limida: <code>retrofit-core = { group = &quot;com.squareup.retrofit2&quot;, name = &quot;retrofit&quot;, version.ref = &quot;retrofit&quot; }</code> va <code>retrofit-gson = { group = &quot;com.squareup.retrofit2&quot;, name = &quot;converter-gson&quot;, version.ref = &quot;retrofit&quot; }</code>;</li><li><code>[bundles]</code> bo&#39;limida: <code>networking = [&quot;retrofit-core&quot;, &quot;retrofit-gson&quot;]</code>.</li></ul></li><li><code>app/build.gradle</code> faylining <code>dependencies</code> blokida butun to&#39;plamni bitta qatorda ulang: <ul><li><code>implementation libs.bundles.networking</code></li></ul></li><li>&quot;Sync Now&quot; bosib, kutubxonalar muvaffaqiyatli yuklanganiga ishonch hosil qiling.</li></ol><hr>',11))])])}const k=e(u,[["render",f]]);export